// Define the abstraction - closed for modification
interface PaymentProcessor {
    void processPayment(double amount);
}

// First implementation
class CreditCardProcessor implements PaymentProcessor {
    public void processPayment(double amount) {
        System.out.println("Processing credit card payment: $" + amount);
        // Credit card-specific logic
    }
}

// Second implementation - extension without modifying existing code
class PayPalProcessor implements PaymentProcessor {
    public void processPayment(double amount) {
        System.out.println("Processing PayPal payment: $" + amount);
        // PayPal-specific logic
    }
}

@Service
class OrderService {
    private final PaymentProcessor processor;

    // Depends on abstraction, not concrete type
    public OrderService(PaymentProcessor processor) {
        this.processor = processor;
    }

    public void checkout(double total) {
        processor.processPayment(total);  // Works with any implementation
    }
}

// The abstraction - defines the contract
interface DiscountStrategy {
    double applyDiscount(double amount);
}

// Implementation 1: Percentage discount
class PercentageDiscount implements DiscountStrategy {
    private final double percentage;

    public PercentageDiscount(double percentage) {
        this.percentage = percentage;
    }

    public double applyDiscount(double amount) {
        return amount * (1 - percentage / 100);
    }
}

// Implementation 2: Fixed amount discount
class FixedAmountDiscount implements DiscountStrategy {
    private final double discountAmount;

    public FixedAmountDiscount(double discountAmount) {
        this.discountAmount = discountAmount;
    }

    public double applyDiscount(double amount) {
        return Math.max(0, amount - discountAmount);
    }
}

@Service
class PricingService {
    private final DiscountStrategy discountStrategy;

    // Injected by Spring - depends on interface only
    public PricingService(DiscountStrategy discountStrategy) {
        this.discountStrategy = discountStrategy;
    }

    public double calculateFinalPrice(double basePrice) {
        return discountStrategy.applyDiscount(basePrice);
    }
}

// Adding new strategy later - zero changes to PricingService
class BuyOneGetOneDiscount implements DiscountStrategy {
    public double applyDiscount(double amount) {
        return amount * 0.5;  // 50% off for BOGO
    }
}

// BEFORE: Type-switching antipattern (OCP violation)
class ShippingCalculatorBad {
    public double calculateCost(String method, double weight) {
        if (method.equals("GROUND")) {
            return weight * 1.5;
        } else if (method.equals("EXPRESS")) {
            return weight * 3.0 + 10;
        } else if (method.equals("OVERNIGHT")) {
            return weight * 5.0 + 20;
        }
        throw new IllegalArgumentException("Unknown method: " + method);
        // Adding AIR_FREIGHT means modifying this method
    }
}

// AFTER: Polymorphic approach (OCP compliant)
interface ShippingMethod {
    double calculateCost(double weight);
}

class GroundShipping implements ShippingMethod {
    public double calculateCost(double weight) {
        return weight * 1.5;
    }
}

class ExpressShipping implements ShippingMethod {
    public double calculateCost(double weight) {
        return weight * 3.0 + 10;
    }
}

class OvernightShipping implements ShippingMethod {
    public double calculateCost(double weight) {
        return weight * 5.0 + 20;
    }
}

@Service
class ShippingCalculatorGood {
    public double calculateCost(ShippingMethod method, double weight) {
        return method.calculateCost(weight);  // No if-else needed
    }
    // Adding AirFreightShipping requires zero changes here
}

// Strategy pattern: swap sorting algorithms
interface SortStrategy {
    void sort(List<Integer> numbers);
}

class QuickSort implements SortStrategy {
    public void sort(List<Integer> numbers) {
        Collections.sort(numbers);  // Using built-in quick sort
    }
}

class BubbleSort implements SortStrategy {
    public void sort(List<Integer> numbers) {
        // Bubble sort implementation
    }
}

// Decorator pattern: add logging to any strategy
class LoggingSortDecorator implements SortStrategy {
    private final SortStrategy wrapped;

    public LoggingSortDecorator(SortStrategy wrapped) {
        this.wrapped = wrapped;
    }

    public void sort(List<Integer> numbers) {
        System.out.println("Sorting started with " + numbers.size() + " items");
        wrapped.sort(numbers);
        System.out.println("Sorting completed");
    }
}

@Service
class DataProcessor {
    private final SortStrategy sortStrategy;

    public DataProcessor(SortStrategy sortStrategy) {
        this.sortStrategy = sortStrategy;
    }

    public void processData(List<Integer> data) {
        sortStrategy.sort(data);  // Extends via strategy, decorates via wrapper
    }
}

